import java.io.*;
import java.util.Base64;
import java.util.Set;

public class SafeDeserializationExample {
    // Define a whitelist of allowed classes to prevent arbitrary code execution
    private static final Set<String> ALLOWED_CLASSES = Set.of("com.example.UserDTO", "java.util.ArrayList");

    public Object deserializeData(String base64Data) throws Exception {
        byte[] data = Base64.getDecoder().decode(base64Data);
        ByteArrayInputStream bais = new ByteArrayInputStream(data);

        // Use a custom ObjectInputStream that validates class types before instantiation
        ObjectInputStream ois = new ObjectInputStream(bais) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                if (!ALLOWED_CLASSES.contains(desc.getName())) {
                    throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
                }
                return super.resolveClass(desc);
            }
        };

        return ois.readObject();
    }
}
